class MessBill:
    """Does everything: the maths, the receipt text, and the saving."""

    def __init__(self, student, days, rate):
        self.student, self.days, self.rate = student, days, rate

    def total(self):
        base = self.days * self.rate
        return round(base * 1.05)          # 5% tax, hard-coded here

    def receipt(self):
        return f"{self.student}: {self.days} days x Rs {self.rate} = Rs {self.total()} (incl. tax)"

    def save(self, ledger):
        ledger.append(self.receipt())      # pretend this is a file or a database


ledger = []
MessBill("Aditi", 30, 90).save(ledger)
print(ledger[0])

class BillCalculator:
    def __init__(self, tax_rate):
        self.tax_rate = tax_rate

    def total(self, days, rate):
        return round(days * rate * (1 + self.tax_rate))


class ReceiptFormatter:
    def line(self, student, days, rate, total):
        return f"{student}: {days} days x Rs {rate} = Rs {total} (incl. tax)"


class Ledger:
    def __init__(self):
        self.rows = []

    def save(self, text):
        self.rows.append(text)


def bill_student(student, days, rate, calc, fmt, ledger):
    total = calc.total(days, rate)
    ledger.save(fmt.line(student, days, rate, total))
    return total


ledger = Ledger()
bill_student("Aditi", 30, 90, BillCalculator(0.05), ReceiptFormatter(), ledger)
bill_student("Bilal", 26, 90, BillCalculator(0.12), ReceiptFormatter(), ledger)  # tax rule changed: one class
print("\n".join(ledger.rows))
